export type AutomationAssignActionType = 'assign';

export type AutomationPriorityActionType = 'priority';

/**
 * @pattern ^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-7[0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$
 */
